/**
 * US-06 — parse_tracking_request (Telegram Bot API).
 *
 * Authorization: Telegram signs the webhook with the header
 * X-Telegram-Bot-Api-Secret-Token (looked up case-insensitively). The n8n
 * assembly passes process.env.TELEGRAM_WEBHOOK_SECRET. A mismatch emits an
 * EMPTY array — a silent drop, because responseMode onReceived already
 * returned the immediate 200 (RNF-01) before this node runs.
 * Outputs ONE item { chat_id, codigo_far?, rut? } or an EMPTY array.
 * Never throws: malformed payloads are dropped silently.
 */
const CODE_PATTERN = /FAR-\d{4}/i;
const RUT_PATTERN = /\b(\d{1,2}\.?\d{3}\.?\d{3}-[\dkK])\b/;

function isAuthorized(headers, secret) {
  if (!headers || typeof headers !== 'object') return false;
  if (typeof secret !== 'string' || !secret) return false;
  const key = Object.keys(headers).find(
    (name) =>
      typeof name === 'string' &&
      name.toLowerCase() === 'x-telegram-bot-api-secret-token'
  );
  if (!key) return false;
  const value = headers[key];
  return typeof value === 'string' && value === secret;
}

/**
 * Pure parser: one Telegram update -> ONE item { chat_id, codigo_far?, rut? }
 * or an EMPTY array (unauthorized, no message, no code and no RUT).
 */
function parseTelegramUpdate(update, headers, secret) {
  if (!isAuthorized(headers, secret)) return [];
  if (!update || typeof update !== 'object') return [];
  const message = update.message;
  if (!message || typeof message !== 'object') return [];
  const chat =
    message.chat &&
    (typeof message.chat.id === 'string' || typeof message.chat.id === 'number')
      ? String(message.chat.id)
      : '';
  if (!chat) return [];
  const text = typeof message.text === 'string' ? message.text : '';
  const extracted = { chat_id: chat };
  const codeMatch = text.match(CODE_PATTERN);
  if (codeMatch) extracted.codigo_far = '#' + codeMatch[0].toUpperCase();
  const rutMatch = text.match(RUT_PATTERN);
  if (rutMatch) extracted.rut = rutMatch[1].replace(/\./g, '').toUpperCase();
  if (extracted.codigo_far || extracted.rut) return [extracted];
  return [];
}

// --- n8n data assembly (guarded so the test harness can load the functions) ---
if (typeof $input !== 'undefined') {
  try {
    const items = $input.all();
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      const json = item && item.json ? item.json : item;
      const headers =
        json && json.headers && typeof json.headers === 'object' ? json.headers : {};
      const update =
        json && json.body && typeof json.body === 'object' ? json.body : json;
      const out = parseTelegramUpdate(
        update,
        headers,
        process.env.TELEGRAM_WEBHOOK_SECRET
      );
      if (out.length) return out; // ONE item per webhook payload
    }
  } catch (err) {
    return []; // malformed payload -> drop, never throw
  }
  return [];
}

function extractCode(text) {
  if (typeof text !== 'string') return null;
  const match = text.match(/FAR-\d{4}/i);
  if (!match) return null;
  return '#' + match[0].toUpperCase();
}

function normalizeRut(value) {
  if (typeof value !== 'string') return null;
  const match = value.match(/\b(\d{1,2}\.?\d{3}\.?\d{3}-[\dkK])\b/);
  if (!match) return null;
  return match[1].replace(/\./g, '').toUpperCase();
}

function extractRut(text) {
  if (typeof text !== 'string') return null;
  return normalizeRut(text);
}

function codeNumber(codigo) {
  const parts = String(codigo === null || codigo === undefined ? '' : codigo).match(/\d+/g);
  if (!parts || !parts.length) return 0;
  return Number(parts[parts.length - 1]) || 0;
}

function sortOrders(list) {
  return list.slice().sort(function (a, b) {
    const ta = Date.parse(a && a.fecha_creacion) || 0;
    const tb = Date.parse(b && b.fecha_creacion) || 0;
    if (ta !== tb) return tb - ta;
    return codeNumber(b.codigo_far) - codeNumber(a.codigo_far);
  });
}

function findOrder(request, catalog) {
  if (!request || typeof request !== 'object' || !Array.isArray(catalog)) return null;
  const rows = catalog.filter(function (row) { return row && typeof row === 'object'; });
  const code = extractCode(typeof request.codigo_far === 'string' ? request.codigo_far : '');
  if (code) {
    const wanted = code.replace(/^#/, '');
    const codeMatches = rows.filter(function (row) {
      const raw = row.codigo_far === null || row.codigo_far === undefined ? '' : String(row.codigo_far);
      return raw.toUpperCase().replace(/^#/, '') === wanted;
    });
    return codeMatches.length ? sortOrders(codeMatches)[0] : null;
  }
  const rut = normalizeRut(typeof request.rut === 'string' ? request.rut : '');
  if (!rut) return null;
  const rutMatches = rows.filter(function (row) {
    const raw = row.rut === null || row.rut === undefined ? '' : String(row.rut);
    return normalizeRut(raw) === rut;
  });
  return rutMatches.length ? sortOrders(rutMatches)[0] : null;
}

function statusMessage(order, dispatch) {
  const rawCode = order && order.codigo_far !== null && order.codigo_far !== undefined ? String(order.codigo_far) : '';
  const code = extractCode(rawCode) || ('#' + rawCode);
  const estado = order && order.estado !== null && order.estado !== undefined ? String(order.estado) : '';
  let message;
  if (estado === 'PENDIENTE_RECETA') {
    message = 'Tu pedido ' + code + ' está esperando la foto de tu receta. Tienes 12 horas para enviarla.';
  } else if (estado === 'RECETA_RECIBIDA') {
    message = 'Recibimos la receta de tu pedido ' + code + '. Ya pasa a preparación.';
  } else if (estado === 'EN_PREPARACION') {
    message = 'Tu pedido ' + code + ' está en preparación en bodega.';
  } else if (estado === 'EN_RUTA') {
    message = 'Tu pedido ' + code + ' va en camino.';
    const eta = dispatch ? Number(dispatch.eta_minutos) : NaN;
    if (Number.isFinite(eta) && eta > 0) {
      message += ' Llegada estimada: ' + eta + ' minutos.';
    }
  } else if (estado === 'ENTREGADO') {
    message = 'Tu pedido ' + code + ' fue entregado.';
  } else if (estado === 'CANCELADO_EXPIRADO') {
    message = 'Tu pedido ' + code + ' fue cancelado por falta de receta después de 12 horas.';
  } else {
    message = 'Tu pedido ' + code + ' está en revisión. Consulta en la farmacia.';
  }
  if (dispatch && dispatch.sector) {
    message += ' Sector: ' + dispatch.sector + '.';
  }
  return message;
}

function buildTrackingReply(request, catalog, dispatches) {
  if (!request || typeof request !== 'object') return null;
  const codigo = extractCode(typeof request.codigo_far === 'string' ? request.codigo_far : '');
  const rut = normalizeRut(typeof request.rut === 'string' ? request.rut : '');
  if (!codigo && !rut) return null;
  const chatId = request.chat_id || '';
  const order = findOrder(request, catalog);
  if (!order) {
    return { chat_id: chatId, message: 'No encontré ese pedido. Revisa el código #FAR-XXXX o tu RUT e inténtalo de nuevo.' };
  }
  const wanted = order.codigo_far === null || order.codigo_far === undefined ? '' : String(order.codigo_far).toUpperCase().replace(/^#/, '');
  const rows = Array.isArray(dispatches) ? dispatches : [];
  let dispatch = null;
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowCode = row && row.codigo_far !== null && row.codigo_far !== undefined ? String(row.codigo_far).toUpperCase().replace(/^#/, '') : '';
    if (rowCode === wanted) {
      dispatch = row;
      break;
    }
  }
  return { chat_id: chatId, message: statusMessage(order, dispatch) };
}

if (typeof $ !== 'undefined') {
  const request = $('parse_tracking_request').first().json;
  const catalog = $('read_ordenes').all();
  const dispatches = $('read_despachos').all();
  const reply = buildTrackingReply(request, catalog, dispatches);
  return reply ? [reply] : [];
}
